def apply(inputs, premises):
    answer = {}
    for i in range(len(inputs["asset_descriptions"])):
        claims = []
        if inputs["illinois_other_property_eligible"][i]:
            claims = claims + [premises["illinois_other_property_citation"]]
        if inputs["federal_household_property_eligible"][i]:
            claims = claims + [premises["federal_household_property_citation"]]
        if inputs["federal_wildcard_eligible"][i]:
            claims = claims + [premises["federal_wildcard_citation"]]
        if inputs["wisconsin_consumer_goods_eligible"][i]:
            claims = claims + [premises["wisconsin_consumer_goods_citation"]]
        answer[inputs["asset_descriptions"][i]] = claims
    return {"answer": answer}

section_1_cited_tax_bracket_claim_decide.procedure:
def apply(inputs, premises):
    in_bracket = inputs["taxable_income"] > inputs["cited_bracket_lower_exclusive"]
    if inputs["cited_bracket_upper_inclusive"] >= 0:
        in_bracket = in_bracket and inputs["taxable_income"] <= inputs["cited_bracket_upper_inclusive"]
    expected_tax = inputs["cited_bracket_base_tax"] + inputs["cited_bracket_rate_percent"] * (inputs["taxable_income"] - inputs["cited_bracket_excess_threshold"]) / 100
    amount_matches = round(expected_tax, 2) == round(inputs["claimed_tax_amount"], 2)
    statement_true = in_bracket and amount_matches
    entailed = statement_true == inputs["claim_affirms_exact_tax"]
    if entailed:
        answer = "Entailment"
    else:
        answer = "Contradiction"
    return {"answer": answer}

